async function forfeitActiveBattleOnUnload(){
    try{
        const playerToken = localStorage.getItem("player_token") || "";

        // PvP: ط·آ·ط¢آ§ط·آ¸أ¢â‚¬آ ط·آ·ط¢آ³ط·آ·ط¢آ­ط·آ·ط¢آ¨ ط·آ¸أ¢â‚¬آ¦ط·آ¸أ¢â‚¬آ  ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ¸أ¢â‚¬آ¦ط·آ·ط¢آ¨ط·آ·ط¢آ§ط·آ·ط¢آ±ط·آ·ط¢آ§ط·آ·ط¢آ© ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ¸أ¢â‚¬آ ط·آ·ط¢آ´ط·آ·ط¢آ·ط·آ·ط¢آ©
        if(typeof window !== "undefined" && typeof window.__pvpActiveMatch === "function"){
            const active = window.__pvpActiveMatch();
            if(active && active.matchId){
                REST_FIREANDFORGET.rpc("pvp_forfeit_match", {
                    p_token: playerToken,
                    p_match_id: active.matchId
                });
            }
        }

        // ط·آ·ط¢آ²ط·آ¸أ¢â‚¬آ ط·آ·ط¢آ²ط·آ·ط¢آ§ط·آ¸أ¢â‚¬آ ط·آ·ط¢آ© ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ¹ط·آ·ط¢آµط·آ·ط¢آ§ط·آ·ط¢آ¨ط·آ·ط¢آ©: ط·آ¸أ¢â‚¬آ¦ط·آ·ط·â€؛ط·آ·ط¢آ§ط·آ·ط¢آ¯ط·آ·ط¢آ±ط·آ·ط¢آ© ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ·ط·â€؛ط·آ·ط¢آ§ط·آ·ط¢آ±ط·آ·ط¢آ© ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ¸أ¢â‚¬آ ط·آ·ط¢آ´ط·آ·ط¢آ·ط·آ·ط¢آ© (ط·آ¸ط¸آ¹ط·آ¸ط¹ث†ط·آ·ط¢آ¹ط·آ·ط¹آ¾ط·آ·ط¢آ¨ط·آ·ط¢آ± ط·آ·ط¢آ³ط·آ·ط¢آ§ط·آ¸أ¢â‚¬ع‘ط·آ·ط¢آ·ط·آ¸أ¢â‚¬آ¹ط·آ·ط¢آ§)
        if(typeof ClanDungeon !== "undefined" && ClanDungeon && typeof ClanDungeon._activeRunId === "function"){
            const runId = ClanDungeon._activeRunId();
            if(runId){
                REST_FIREANDFORGET.rpc("clan_dungeon_leave", {
                    p_token: playerToken,
                    p_run_id: runId
                });
            }
        }
    }catch(e){}
}

