// ط·آ·ط¢آ³ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ³ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ© JavaScript ط·آ·ط¢آ¯ط·آ·ط¢آ§ط·آ·ط¢آ®ط·آ¸أ¢â‚¬â€چ ط·آ·ط¢آ®ط·آ·ط¢آ§ط·آ·ط¢آµط·آ¸ط¸آ¹ط·آ·ط¢آ© HTML
function escapeJsAttr(value){

    return String(value == null ? "" : value)
        .replace(/\\/g, "\\\\")
        .replace(/'/g, "\\'")
        .replace(/"/g, "\\\"")
        .replace(/</g, "\\u003C")
        .replace(/>/g, "\\u003E")
        .replace(/\n/g, "\\n")
        .replace(/\r/g, "\\r");

}

