function getToastContainer(){

    let box = document.getElementById("toast-container");

    if(!box){

        box = document.createElement("div");
        box.id = "toast-container";
        document.body.appendChild(box);

    }

    return box;

}

function classifyToastType(message){

    let text = String(message);

    let errorWords = ["ط·آ·ط¢آ®ط·آ·ط¢آ·ط·آ·ط¢آ£","ط·آ¸ط¸آ¾ط·آ·ط¢آ´ط·آ¸أ¢â‚¬â€چ","ط·آ·ط·â€؛ط·آ¸ط¸آ¹ط·آ·ط¢آ± ط·آ¸أ¢â‚¬آ¦ط·آ·ط¢آµط·آ·ط¢آ±ط·آ·ط¢آ­","ط·آ·ط·â€؛ط·آ¸ط¸آ¹ط·آ·ط¢آ± ط·آ·ط¢آµط·آ·ط¢آ­ط·آ¸ط¸آ¹ط·آ·ط¢آ­","ط·آ·ط·â€؛ط·آ¸ط¸آ¹ط·آ·ط¢آ± ط·آ·ط¢آµط·آ·ط¢آ­ط·آ¸ط¸آ¹ط·آ·ط¢آ­ط·آ·ط¢آ©","ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ§ ط·آ¸ط¸آ¹ط·آ¸أ¢â‚¬آ¦ط·آ¸ط¦â€™ط·آ¸أ¢â‚¬آ ","ط·آ·ط¹آ¾ط·آ·ط¢آ¹ط·آ·ط¢آ°ط·آ¸أ¢â‚¬ع©ط·آ·ط¢آ±","ط·آ·ط¹آ¾ط·آ·ط¢آ¹ط·آ·ط¢آ°ط·آ·ط¢آ±","ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ§ ط·آ¸ط¸آ¹ط·آ¸ط«â€ ط·آ·ط¢آ¬ط·آ·ط¢آ¯","ط·آ¸أ¢â‚¬آ¦ط·آ¸أ¢â‚¬آ¦ط·آ·ط¹آ¾ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ¦","ط·آ¸أ¢â‚¬آ¦ط·آ·ط¢آ±ط·آ¸ط¸آ¾ط·آ¸ط«â€ ط·آ·ط¢آ¶"];
    let successWords = ["ط·آ·ط¹آ¾ط·آ¸أ¢â‚¬آ¦ ","ط·آ¸أ¢â‚¬آ ط·آ·ط¢آ¬ط·آ·ط¢آ­","ط·آ·ط¢آ£ط·آ¸أ¢â‚¬طŒط·آ¸أ¢â‚¬â€چط·آ·ط¢آ§ط·آ¸أ¢â‚¬آ¹","ط·آ¸أ¢â‚¬آ¦ط·آ·ط¢آ±ط·آ·ط¢آ­ط·آ·ط¢آ¨ط·آ·ط¢آ§ط·آ¸أ¢â‚¬آ¹","ط·آ¸أ¢â‚¬آ¦ط·آ·ط¢آ±ط·آ·ط¢آ­ط·آ·ط¢آ¨ط·آ·ط¢آ§"];

    if(errorWords.some(w => text.includes(w))) return "error";
    if(successWords.some(w => text.includes(w))) return "success";

    return "info";

}

function showToast(message){

    let container = getToastContainer();

    let type = classifyToastType(message);

    if(container.children.length >= 3){
        let oldest = container.firstChild;
        if(oldest){
            oldest.classList.remove("show");
            oldest.classList.add("hide");
            setTimeout(() => oldest.remove(), 250);
        }
    }

    let toast = document.createElement("div");
    toast.className = "app-toast " + type;

    let icon =
    type === "error" ? "ط£آ¢ط¹â€کط¢آ ط£آ¯ط¢آ¸ط¹ث†" :
    type === "success" ? "ط£آ¢ط¥â€œأ¢â‚¬آ¦" : "ط£آ¢أ¢â‚¬â€چط¢آ¹ط£آ¯ط¢آ¸ط¹ث†";

    toast.innerHTML =
    `<span class="app-toast-icon">${icon}</span><span class="app-toast-text"></span>`;

    toast.querySelector(".app-toast-text").textContent = String(message);

    container.appendChild(toast);

    requestAnimationFrame(() => toast.classList.add("show"));

    let remove = () => {

        toast.classList.remove("show");
        toast.classList.add("hide");

        setTimeout(() => toast.remove(), 250);

    };

    toast.addEventListener("click", remove);

    setTimeout(remove, 3400);

}

// ط·آ·ط¢آ¨ط·آ·ط¢آ¯ط·آ¸ط¸آ¹ط·آ¸أ¢â‚¬â€چ ط·آ¸أ¢â‚¬آ¦ط·آ¸ط«â€ ط·آ·ط¢آ­ط·آ¸أ¢â‚¬ع©ط·آ·ط¢آ¯ ط·آ¸أ¢â‚¬â€چط·آ¸أ¢â€ڑآ¬ alert() ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ§ط·آ¸ط¸آ¾ط·آ·ط¹آ¾ط·آ·ط¢آ±ط·آ·ط¢آ§ط·آ·ط¢آ¶ط·آ¸ط¸آ¹ ط·آ·ط¢آ¨ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ¸أ¢â‚¬آ¦ط·آ·ط¹آ¾ط·آ·ط¢آµط·آ¸ط¸آ¾ط·آ·ط¢آ­ ط·آ¸ط¸آ¾ط·آ¸ط¸آ¹ ط·آ¸ط¦â€™ط·آ¸أ¢â‚¬â€چ ط·آ·ط¢آ£ط·آ¸أ¢â‚¬آ ط·آ·ط¢آ­ط·آ·ط¢آ§ط·آ·ط·إ’ ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ¸أ¢â‚¬â€چط·آ·ط¢آ¹ط·آ·ط¢آ¨ط·آ·ط¢آ©
function alert(message){

    showToast(message);

}


