//    - ط·آ¸ط¸آ¾ط·آ¸ط¸آ¹ ط·آ¸أ¢â‚¬آ¦ط·آ·ط¹آ¾ط·آ·ط¢آµط·آ¸ط¸آ¾ط·آ·ط¢آ­ ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ¸ط«â€ ط·آ¸ط¸آ¹ط·آ·ط¢آ¨ ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ¹ط·آ·ط¢آ§ط·آ·ط¢آ¯ط·آ¸ط¸آ¹: ط·آ¸أ¢â‚¬آ ط·آ·ط¢آ±ط·آ·ط¢آ¬ط·آ·ط¢آ¹ ط·آ¸أ¢â‚¬â€چط·آ¸أ¢â‚¬آ¦ط·آ·ط¢آ¹ط·آ·ط¢آ±ط·آ¸أ¢â‚¬ع©ط·آ¸ط¸آ¾ ط·آ·ط¢آ¹ط·آ·ط¢آ´ط·آ¸ط«â€ ط·آ·ط¢آ§ط·آ·ط¢آ¦ط·آ¸ط¸آ¹ ط·آ¸أ¢â‚¬آ¦ط·آ·ط¢آ®ط·آ·ط¢آ²ط·آ¸ط¹ع©ط·آ¸أ¢â‚¬ع©ط·آ¸أ¢â‚¬آ  ط·آ¸ط¸آ¾ط·آ¸ط¸آ¹ localStorage
//      (ط·آ¸ط¸آ¹ط·آ·ط¢آ¨ط·آ¸أ¢â‚¬ع‘ط·آ¸أ¢â‚¬آ° ط·آ¸أ¢â‚¬آ¦ط·آ¸ط«â€ ط·آ·ط¢آ¬ط·آ¸ط«â€ ط·آ·ط¢آ¯ ط·آ¸أ¢â‚¬آ¦ط·آ·ط¢آ§ ط·آ¸أ¢â‚¬â€چط·آ¸أ¢â‚¬آ¦ ط·آ¸ط¸آ¹ط·آ¸أ¢â‚¬آ¦ط·آ·ط¢آ³ط·آ·ط¢آ­ ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ¸أ¢â‚¬آ¦ط·آ·ط¢آ³ط·آ·ط¹آ¾ط·آ·ط¢آ®ط·آ·ط¢آ¯ط·آ¸أ¢â‚¬آ¦ ط·آ·ط¢آ¨ط·آ¸ط¸آ¹ط·آ·ط¢آ§ط·آ¸أ¢â‚¬آ ط·آ·ط¢آ§ط·آ·ط¹آ¾ ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ¸أ¢â‚¬آ¦ط·آ¸ط«â€ ط·آ¸أ¢â‚¬ع‘ط·آ·ط¢آ¹).
let cachedDeviceId = null;

async function getDeviceId(){

    if(cachedDeviceId) return cachedDeviceId;

    // ط·آ¸أ¢â‚¬آ ط·آ¸ط¦â€™ط·آ·ط¹آ¾ط·آ·ط¢آ´ط·آ¸ط¸آ¾ ط·آ·ط¹آ¾ط·آ¸أ¢â‚¬â€چط·آ¸أ¢â‚¬ع‘ط·آ·ط¢آ§ط·آ·ط¢آ¦ط·آ¸ط¸آ¹ط·آ¸أ¢â‚¬آ¹ط·آ·ط¢آ§ ط·آ·ط¢آ¥ط·آ·ط¢آ°ط·آ·ط¢آ§ ط·آ¸ط¦â€™ط·آ¸أ¢â‚¬آ ط·آ·ط¢آ§ ط·آ·ط¢آ¯ط·آ·ط¢آ§ط·آ·ط¢آ®ط·آ¸أ¢â‚¬â€چ ط·آ·ط¹آ¾ط·آ·ط¢آ·ط·آ·ط¢آ¨ط·آ¸ط¸آ¹ط·آ¸أ¢â‚¬ع‘ Capacitor ط·آ¸ط«â€ ط·آ·ط¢آ¥ط·آ·ط¢آ°ط·آ·ط¢آ§ ط·آ¸ط¦â€™ط·آ·ط¢آ§ط·آ¸أ¢â‚¬آ ط·آ·ط¹آ¾ ط·آ·ط¢آ¥ط·آ·ط¢آ¶ط·آ·ط¢آ§ط·آ¸ط¸آ¾ط·آ·ط¢آ©
    // Device ط·آ¸أ¢â‚¬آ¦ط·آ·ط¢آ¶ط·آ·ط¢آ§ط·آ¸ط¸آ¾ط·آ·ط¢آ© ط·آ¸ط«â€ ط·آ¸أ¢â‚¬آ¦ط·آ·ط¢آ³ط·آ·ط¢آ¬ط·آ¸ط¹ع©ط·آ¸أ¢â‚¬ع©ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ© (window.Capacitor.Plugins.Device)
    if(window.Capacitor
    && window.Capacitor.isNativePlatform
    && window.Capacitor.isNativePlatform()
    && window.Capacitor.Plugins
    && window.Capacitor.Plugins.Device){

        try{
            let info = await window.Capacitor.Plugins.Device.getId();
            // info.identifier = ANDROID_ID ط·آ·ط¢آ¹ط·آ¸أ¢â‚¬â€چط·آ¸أ¢â‚¬آ° ط·آ·ط¢آ£ط·آ¸أ¢â‚¬آ ط·آ·ط¢آ¯ط·آ·ط¢آ±ط·آ¸ط«â€ ط·آ¸ط¸آ¹ط·آ·ط¢آ¯ ط£آ¢أ¢â€ڑآ¬أ¢â‚¬â€Œ ط·آ¸ط¸آ¾ط·آ·ط¢آ±ط·آ¸ط¸آ¹ط·آ·ط¢آ¯ ط·آ¸أ¢â‚¬â€چط·آ¸ط¦â€™ط·آ¸أ¢â‚¬â€چ ط·آ·ط¢آ¬ط·آ¸أ¢â‚¬طŒط·آ·ط¢آ§ط·آ·ط¢آ² ط·آ¸أ¢â‚¬آ¦ط·آ·ط¢آ§ط·آ·ط¢آ¯ط·آ¸ط¸آ¹
            if(info && info.identifier){
                cachedDeviceId = "native:" + info.identifier;
                return cachedDeviceId;
            }
        }catch(e){
            console.log("ط·آ·ط¹آ¾ط·آ·ط¢آ¹ط·آ·ط¢آ°ط·آ¸أ¢â‚¬ع©ط·آ·ط¢آ± ط·آ·ط¢آ¬ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ¨ ط·آ¸أ¢â‚¬آ¦ط·آ·ط¢آ¹ط·آ·ط¢آ±ط·آ¸أ¢â‚¬ع©ط·آ¸ط¸آ¾ ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ¬ط·آ¸أ¢â‚¬طŒط·آ·ط¢آ§ط·آ·ط¢آ² ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ£ط·آ·ط¢آµط·آ¸أ¢â‚¬â€چط·آ¸ط¸آ¹ط·آ·ط¥â€™ ط·آ·ط¢آ§ط·آ·ط¢آ³ط·آ·ط¹آ¾ط·آ·ط¢آ®ط·آ·ط¢آ¯ط·آ·ط¢آ§ط·آ¸أ¢â‚¬آ¦ ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ¨ط·آ·ط¢آ¯ط·آ¸ط¸آ¹ط·آ¸أ¢â‚¬â€چ", e);
        }
    }

    // ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ¨ط·آ·ط¢آ¯ط·آ¸ط¸آ¹ط·آ¸أ¢â‚¬â€چ (ط·آ¸أ¢â‚¬آ¦ط·آ·ط¹آ¾ط·آ·ط¢آµط·آ¸ط¸آ¾ط·آ·ط¢آ­ ط·آ¸ط«â€ ط·آ¸ط¸آ¹ط·آ·ط¢آ¨ ط·آ·ط¢آ¹ط·آ·ط¢آ§ط·آ·ط¢آ¯ط·آ¸ط¸آ¹ط·آ·ط¥â€™ ط·آ·ط¢آ£ط·آ¸ط«â€  ط·آ¸ط¸آ¾ط·آ·ط¢آ´ط·آ¸أ¢â‚¬â€چ ط·آ·ط¢آ¬ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ¨ ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ¸أ¢â‚¬آ¦ط·آ·ط¢آ¹ط·آ·ط¢آ±ط·آ¸أ¢â‚¬ع©ط·آ¸ط¸آ¾ ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ£ط·آ·ط¢آµط·آ¸أ¢â‚¬â€چط·آ¸ط¸آ¹)
    let id = localStorage.getItem("device_id");
    if(!id){
        id = (crypto.randomUUID ? crypto.randomUUID() :
            "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, c => {
                const r = Math.random() * 16 | 0;
                const v = c === "x" ? r : (r & 0x3 | 0x8);
                return v.toString(16);
            }));
        localStorage.setItem("device_id", id);
    }
    cachedDeviceId = "web:" + id;
    return cachedDeviceId;
}

// 2) ط·آ·ط¢آ¨ط·آ·ط¢آµط·آ¸أ¢â‚¬آ¦ط·آ·ط¢آ© ط·آ·ط¢آ¬ط·آ¸أ¢â‚¬طŒط·آ·ط¢آ§ط·آ·ط¢آ² ط·آ¸أ¢â‚¬آ¦ط·آ·ط¢آ¨ط·آ¸أ¢â‚¬آ ط·آ¸ط¸آ¹ط·آ·ط¢آ© ط·آ¸أ¢â‚¬آ¦ط·آ¸أ¢â‚¬آ  ط·آ·ط¢آ®ط·آ·ط¢آµط·آ·ط¢آ§ط·آ·ط¢آ¦ط·آ·ط¢آµ ط·آ·ط¢آ«ط·آ·ط¢آ§ط·آ·ط¢آ¨ط·آ·ط¹آ¾ط·آ·ط¢آ© (ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ§ ط·آ·ط¹آ¾ط·آ·ط¢آ¹ط·آ·ط¹آ¾ط·آ¸أ¢â‚¬آ¦ط·آ·ط¢آ¯ ط·آ·ط¢آ¹ط·آ¸أ¢â‚¬â€چط·آ¸أ¢â‚¬آ° ط·آ·ط¢آ£ط·آ¸ط¸آ¹ ط·آ·ط¹آ¾ط·آ·ط¢آ®ط·آ·ط¢آ²ط·آ¸ط¸آ¹ط·آ¸أ¢â‚¬آ )
//    ط·آ·ط¹آ¾ط·آ·ط¢آ¨ط·آ¸أ¢â‚¬ع‘ط·آ¸أ¢â‚¬آ° ط·آ·ط¢آ´ط·آ·ط¢آ¨ط·آ¸أ¢â‚¬طŒ ط·آ·ط¢آ«ط·آ·ط¢آ§ط·آ·ط¢آ¨ط·آ·ط¹آ¾ط·آ·ط¢آ© ط·آ·ط¢آ­ط·آ·ط¹آ¾ط·آ¸أ¢â‚¬آ° ط·آ¸أ¢â‚¬â€چط·آ¸ط«â€  ط·آ¸أ¢â‚¬آ¦ط·آ·ط¢آ³ط·آ·ط¢آ­ ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ¸أ¢â‚¬آ¦ط·آ·ط¢آ³ط·آ·ط¹آ¾ط·آ·ط¢آ®ط·آ·ط¢آ¯ط·آ¸أ¢â‚¬آ¦ ط·آ·ط¢آ¨ط·آ¸ط¸آ¹ط·آ·ط¢آ§ط·آ¸أ¢â‚¬آ ط·آ·ط¢آ§ط·آ·ط¹آ¾ ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ¸أ¢â‚¬آ¦ط·آ·ط¹آ¾ط·آ·ط¢آµط·آ¸ط¸آ¾ط·آ·ط¢آ­
async function getDeviceFingerprint(){
    const parts = [];

    parts.push(navigator.userAgent || "");
    parts.push(navigator.platform || "");
    parts.push(navigator.language || "");
    parts.push(String(navigator.hardwareConcurrency || ""));
    parts.push(String(navigator.deviceMemory || ""));
    parts.push(String(screen.width) + "x" + String(screen.height));
    parts.push(String(screen.colorDepth || ""));
    parts.push(Intl.DateTimeFormat().resolvedOptions().timeZone || "");

    // ط·آ·ط¢آ¨ط·آ·ط¢آµط·آ¸أ¢â‚¬آ¦ط·آ·ط¢آ© ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ±ط·آ·ط¢آ³ط·آ¸أ¢â‚¬آ¦ (canvas) ط£آ¢أ¢â€ڑآ¬أ¢â‚¬â€Œ ط·آ·ط¹آ¾ط·آ·ط¢آ®ط·آ·ط¹آ¾ط·آ¸أ¢â‚¬â€چط·آ¸ط¸آ¾ ط·آ·ط¢آ­ط·آ·ط¢آ³ط·آ·ط¢آ¨ ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ¬ط·آ¸أ¢â‚¬طŒط·آ·ط¢آ§ط·آ·ط¢آ²/ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ¸أ¢â‚¬آ¦ط·آ·ط¹آ¾ط·آ·ط¢آµط·آ¸ط¸آ¾ط·آ·ط¢آ­/ط·آ·ط¹آ¾ط·آ·ط¢آ¹ط·آ·ط¢آ±ط·آ¸ط¸آ¹ط·آ¸ط¸آ¾ ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ´ط·آ·ط¢آ§ط·آ·ط¢آ´ط·آ·ط¢آ©
    try{
        const canvas = document.createElement("canvas");
        const ctx = canvas.getContext("2d");
        ctx.textBaseline = "top";
        ctx.font = "14px Arial";
        ctx.fillText("device-fp-ط¸â€¹ط¹ط›ط¹ع©ط¢آ®-card-game", 2, 2);
        parts.push(canvas.toDataURL());
    }catch(e){ parts.push("no-canvas"); }

    // ط·آ·ط¢آ¨ط·آ·ط¢آµط·آ¸أ¢â‚¬آ¦ط·آ·ط¢آ© WebGL (ط·آ¸أ¢â‚¬آ ط·آ¸ط«â€ ط·آ·ط¢آ¹ ط·آ¸ط¦â€™ط·آ·ط¢آ±ط·آ·ط¹آ¾ ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ´ط·آ·ط¢آ§ط·آ·ط¢آ´ط·آ·ط¢آ©)
    try{
        const gl = document.createElement("canvas").getContext("webgl");
        const dbgInfo = gl.getExtension("WEBGL_debug_renderer_info");
        if(dbgInfo){
            parts.push(gl.getParameter(dbgInfo.UNMASKED_VENDOR_WEBGL));
            parts.push(gl.getParameter(dbgInfo.UNMASKED_RENDERER_WEBGL));
        }
    }catch(e){ parts.push("no-webgl"); }

    const raw = parts.join("|||");

    // ط·آ·ط¹آ¾ط·آ·ط¢آ¬ط·آ·ط¢آ²ط·آ·ط¢آ¦ط·آ·ط¢آ© (hash) ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ¸أ¢â‚¬ع‘ط·آ¸ط¸آ¹ط·آ¸أ¢â‚¬آ¦ط·آ·ط¢آ© ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ¸أ¢â‚¬آ ط·آ¸أ¢â‚¬طŒط·آ·ط¢آ§ط·آ·ط¢آ¦ط·آ¸ط¸آ¹ط·آ·ط¢آ© ط·آ·ط¢آ¥ط·آ¸أ¢â‚¬â€چط·آ¸أ¢â‚¬آ° SHA-256
    const enc = new TextEncoder().encode(raw);
    const hashBuffer = await crypto.subtle.digest("SHA-256", enc);
    const hashArray = Array.from(new Uint8Array(hashBuffer));
    return hashArray.map(b => b.toString(16).padStart(2, "0")).join("");
}


