function renderMonsterList(monsters){

    let box = document.getElementById("pve-monster-list");

    if(!box) return;

    if(!monsters || monsters.length === 0){

        box.innerHTML = "<p>ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ§ ط·آ·ط¹آ¾ط·آ¸ط«â€ ط·آ·ط¢آ¬ط·آ·ط¢آ¯ ط·آ¸ط«â€ ط·آ·ط¢آ­ط·آ¸ط«â€ ط·آ·ط¢آ´ ط·آ¸أ¢â‚¬آ¦ط·آ·ط¹آ¾ط·آ·ط¢آ§ط·آ·ط¢آ­ط·آ·ط¢آ© ط·آ·ط¢آ­ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ¸ط¸آ¹ط·آ¸أ¢â‚¬آ¹ط·آ·ط¢آ§</p>";

        return;

    }

    box.innerHTML = "";

    monsters.forEach(monster => {

        let card = document.createElement("div");

        card.className = "character-card";

        card.innerHTML = `

        <div class="character-info">

            <h3>${escapeHtml(monster.name)}</h3>

            <p>ط£آ¢أ¢â‚¬إ’ط¢آ¤ط£آ¯ط¢آ¸ط¹ث† ${monster.hp || 0} &nbsp;ط·آ¢ط¢آ·&nbsp; ط£آ¢ط¹â€کأ¢â‚¬â€Œط£آ¯ط¢آ¸ط¹ث† ${monster.atk || 0}</p>

            ${(monster.gold_prize || 0) > 0
                ? `<p>ط¸â€¹ط¹ط›ط¹آ¾أ¢â€‍آ¢ ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ¬ط·آ·ط¢آ§ط·آ·ط¢آ¦ط·آ·ط¢آ²ط·آ·ط¢آ©: ${monster.gold_prize} ط·آ·ط¢آ°ط·آ¸أ¢â‚¬طŒط·آ·ط¢آ¨ ط·آ¢ط¢آ· ط·آ¸أ¢â‚¬آ¦ط·آ·ط¹آ¾ط·آ·ط¢آ¨ط·آ¸أ¢â‚¬ع‘ط·آ¸ط¸آ¹ ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ¸ط¸آ¹ط·آ¸ط«â€ ط·آ¸أ¢â‚¬آ¦: ${monster.remaining_today}</p>`
                : `<p>ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ§ ط·آ·ط¢آ¬ط·آ·ط¢آ§ط·آ·ط¢آ¦ط·آ·ط¢آ²ط·آ·ط¢آ© ط·آ·ط¢آ°ط·آ¸أ¢â‚¬طŒط·آ·ط¢آ¨ ط·آ¸أ¢â‚¬â€چط·آ¸أ¢â‚¬طŒط·آ·ط¢آ°ط·آ·ط¢آ§ ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ¸ط«â€ ط·آ·ط¢آ­ط·آ·ط¢آ´</p>`}

        </div>

        <button>ط£آ¢ط¹â€کأ¢â‚¬â€Œط£آ¯ط¢آ¸ط¹ث† ط·آ¸أ¢â‚¬ع‘ط·آ·ط¢آ§ط·آ·ط¹آ¾ط·آ¸أ¢â‚¬â€چ</button>

        `;

        card.querySelector("button").onclick = () => startPVEBattle(monster.id);

        // قفل الوحوش التي يتطلب مواجهتها مستوى أعلى من مستوى اللاعب
        {
        let monsterMin = Number(monster.min_level) || 0;

        let myLevel = Number(monster.player_level) || 1;

        if(monsterMin > 0 && myLevel < monsterMin){

            card.classList.add("level-locked");

            let btn = card.querySelector("button");

            if(btn){

                btn.textContent = "🔒 يتطلب مستوى " + monsterMin;

                btn.disabled = true;

                btn.onclick = null;

            }

        }

        }

        box.appendChild(card);

    });

}

