async function renderPendingCharacterBanner(box){

    let player_id =
    localStorage.getItem(
        "player_id"
    );


    if(!player_id) return;


    let {data:list, error}=
    await supabaseClient
    .from("characters")
    .select("id,name,status")
    .eq("requested_by",player_id)
    .in("status",["pending","approved"]);


    if(error || !list || list.length === 0) return;


    let pending =
    (list.find(function(c){ return c.status === "pending"; }) || null);


    let approved =
    (list.find(function(c){ return c.status === "approved"; }) || null);


    let html =
    "";


    if(pending){

        html +=
        `<div class="pending-character-banner">
            ⏳ شخصيتك المطلوبة "<b>${escapeHtml(pending.name)}</b>" قيد المراجعة، انتظر موافقة الأدمن.
        </div>`;

    }else if(approved){

        html +=
        `<div class="pending-character-banner">
            ✅ شخصيتك "<b>${escapeHtml(approved.name)}</b>" تم اعتمادها! اختر أدناه أو ادخل للعبة.
        </div>`;

    }


    if(html){

        box.innerHTML += html;

    }

}

