function showCharacterRequest(){
    openScreen("character-request-screen");
}

function submitCharacterRequest(){
    sendCharacterRequest();
}

async function sendCharacterRequest(){

    let playerToken =
    localStorage.getItem(
        "player_token"
    );


    if(!playerToken){

        alert(
        "ظٹط¬ط¨ طھط³ط¬ظٹظ„ ط§ظ„ط¯ط®ظˆظ„ ظƒظ„ط§ط¹ط¨ ط£ظˆظ„ظ‹ط§"
        );


        return;

    }


    let name =
    document
    .getElementById(
        "requested-character-name"
    )
    .value
    .trim();



    let anime =
    document
    .getElementById(
        "requested-character-anime"
    )
    .value
    .trim();



    let note =
    document
    .getElementById(
        "requested-character-notes"
    )
    .value
    .trim();





    if(name==="" || anime===""){


        alert(
        "ط§ظƒطھط¨ ط§ط³ظ… ط§ظ„ط´ط®طµظٹط© ظˆط§ظ„ط£ظ†ظ…ظٹ"
        );


        return;

    }


    let prompt = "ط£ظ†ط´ط¦ ط´ط®طµظٹط© ط¨ط§ط³ظ… \"" + name +
        "\" ظ…ظ† ط£ظ†ظ…ظٹ \"" + anime + "\"" +
        (note ? " ظ…ط¹ ظ‡ط°ظ‡ ط§ظ„ظ…ظ„ط§ط­ط¸ط§طھ: " + note : "");


    let submitBtn =
    document.getElementById(
        "requested-character-submit"
    );


    if(submitBtn){
        submitBtn.disabled = true;
        submitBtn.textContent = "ط¬ط§ط±ظٹ ط§ظ„طھط­ط¶ظٹط±...";
    }


    try{

        let res =
        await fetch(
            SUPABASE_URL + "/functions/v1/admin-ai",
            {
                method: "POST",
                headers: {
                    "Content-Type": "application/json",
                    "apikey": SUPABASE_KEY,
                    "Authorization": "Bearer " + SUPABASE_KEY
                },
                body: JSON.stringify({
                    player_token: playerToken,
                    entity_type: "character",
                    prompt: prompt
                })
            }
        );


        let json =
        await res.json();


        if(!res.ok || !json.ok){

            alert(
            (json && json.error) || "ظپط´ظ„ ط§ظ„طھط­ط¶ظٹط±"
            );


            return;

        }


        alert(
        "طھظ… ط¥ط±ط³ط§ظ„ ط§ظ„ط·ظ„ط¨ ظ„ظ„ظ…ط±ط§ط¬ط¹ط©"
        );


        [
            "requested-character-name",
            "requested-character-anime",
            "requested-character-notes"
        ].forEach(function(id){

            let el =
            document.getElementById(id);

            if(el) el.value = "";

        });


        openScreen(
        "character-choice-screen"
        );


        loadAvailableCharacters();

    }catch(e){


        alert(
        "ط®ط·ط£ ظپظٹ ط§ظ„ط§طھطµط§ظ„ ط¨ط§ظ„ط®ط§ط¯ظ…"
        );


    }finally{


        if(submitBtn){
            submitBtn.disabled = false;
            submitBtn.textContent = "ًں“© ط¥ط±ط³ط§ظ„ ط§ظ„ط·ظ„ط¨";
        }

    }

}
