function renderPlayerScreen(player){

    if(player.has_character === true){


        openScreen(
            "home-screen"
        );


    }else{


        openScreen(
            "character-choice-screen"
        );


        loadAvailableCharacters();


    }



    updatePlayerInfo();

    // ط·آ·ط¢آ£ط·آ·ط¢آ¨ط·آ¸أ¢â‚¬ع‘ط·آ¸ط¹آ¯ ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ¸أ¢â‚¬â€چط·آ·ط¢آ§ط·آ·ط¢آ¹ط·آ·ط¢آ¨ "ط·آ¸أ¢â‚¬آ¦ط·آ·ط¹آ¾ط·آ·ط¢آµط·آ¸أ¢â‚¬â€چط·آ¸أ¢â‚¬آ¹ط·آ·ط¢آ§" ط·آ¸ط¸آ¾ط·آ¸ط¸آ¹ ط·آ¸أ¢â‚¬ع‘ط·آ·ط¢آ§ط·آ·ط¢آ¦ط·آ¸أ¢â‚¬آ¦ط·آ·ط¢آ© PvP ط·آ¸ط«â€ ط·آ·ط¢آ§ط·آ·ط¢آ³ط·آ·ط¹آ¾ط·آ¸أ¢â‚¬ع‘ط·آ·ط¢آ¨ط·آ¸أ¢â‚¬â€چ ط·آ·ط¹آ¾ط·آ·ط¢آ­ط·آ·ط¢آ¯ط·آ¸أ¢â‚¬ع©ط·آ¸ط¸آ¹ط·آ·ط¢آ§ط·آ·ط¹آ¾ ط·آ·ط¢آ£ط·آ¸ط¸آ¹ ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ§ط·آ·ط¢آ¹ط·آ·ط¢آ¨ ط·آ·ط¢آ¢ط·آ·ط¢آ®ط·آ·ط¢آ± ط·آ¸أ¢â‚¬آ¦ط·آ¸أ¢â‚¬آ  ط·آ·ط¢آ£ط·آ¸ط¸آ¹ ط·آ·ط¢آ´ط·آ·ط¢آ§ط·آ·ط¢آ´ط·آ·ط¢آ©
    startPlayerPresence();

}






