function stopPlayerPresence(){
    if(presenceTimer){ clearInterval(presenceTimer); presenceTimer = null; }
    if(challengePollTimer){ clearInterval(challengePollTimer); challengePollTimer = null; }
    hideGlobalChallengeBanner();
}

function renderGlobalChallengeBanner(inc){
    let box = document.getElementById("global-challenge-banner");
    if(!box) return;

    // ط·آ·ط¢آ¯ط·آ·ط¢آ§ط·آ·ط¢آ®ط·آ¸أ¢â‚¬â€چ ط·آ·ط¢آ±ط·آ·ط¢آ¯ط·آ¸أ¢â‚¬طŒط·آ·ط¢آ© PvP ط·آ·ط¢آ£ط·آ¸ط«â€  ط·آ¸أ¢â‚¬آ ط·آ·ط¢آ²ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چ ط·آ¸ط¸آ¾ط·آ·ط¢آ¹ط·آ¸أ¢â‚¬â€چط·آ¸ط¸آ¹: ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ±ط·آ·ط¢آ¯ط·آ¸أ¢â‚¬طŒط·آ·ط¢آ© ط·آ·ط¹آ¾ط·آ·ط¢آ¹ط·آ·ط¢آ±ط·آ·ط¢آ¶ ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ·ط¹آ¾ط·آ·ط¢آ­ط·آ·ط¢آ¯ط·آ¸ط¸آ¹ ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ¸ط«â€ ط·آ·ط¢آ§ط·آ·ط¢آ±ط·آ·ط¢آ¯ ط·آ·ط¢آ¨ط·آ¸أ¢â‚¬آ ط·آ¸ط¸آ¾ط·آ·ط¢آ³ط·آ¸أ¢â‚¬طŒط·آ·ط¢آ§ط·آ·ط¥â€™ ط·آ¸ط¸آ¾ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ§
    // ط·آ¸أ¢â‚¬آ ط·آ·ط¢آ¹ط·آ·ط¢آ±ط·آ·ط¢آ¶ ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ¸أ¢â‚¬â€چط·آ·ط¢آ§ط·آ¸ط¸آ¾ط·آ·ط¹آ¾ط·آ·ط¢آ© ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ¸أ¢â‚¬آ¦ط·آ¸ط¦â€™ط·آ·ط¢آ±ط·آ·ط¢آ±ط·آ·ط¢آ©
    let active = document.querySelector(".screen.active");
    let activeId = active ? active.id : "";
    if(activeId === "pvp-lobby-screen" || activeId === "pvp-battle-screen"){
        hideGlobalChallengeBanner();
        return;
    }

    if(!inc){
        hideGlobalChallengeBanner();
        return;
    }

    box.classList.remove("hidden");
    let safeName = escapeHtml(inc.challenger_name || "ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ§ط·آ·ط¢آ¹ط·آ·ط¢آ¨");
    box.innerHTML =
        `<span class="gcb-text">ط£آ¢ط¹â€کأ¢â‚¬â€Œط£آ¯ط¢آ¸ط¹ث† ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ¯ط·آ¸ط¸آ¹ط·آ¸ط¦â€™ ط·آ·ط¹آ¾ط·آ·ط¢آ­ط·آ·ط¢آ¯ط·آ¸ط¸آ¹ ط·آ¸أ¢â‚¬آ¦ط·آ¸أ¢â‚¬آ  ${safeName}</span>` +
        `<button class="gcb-accept">ط·آ¸أ¢â‚¬ع‘ط·آ·ط¢آ¨ط·آ¸ط«â€ ط·آ¸أ¢â‚¬â€چ</button>` +
        `<button class="gcb-dismiss">ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ§ط·آ·ط¢آ­ط·آ¸أ¢â‚¬ع‘ط·آ¸أ¢â‚¬آ¹ط·آ·ط¢آ§</button>`;
    box.querySelector(".gcb-accept").onclick = () => {
        box.classList.add("hidden");
        try{ pvpRespondChallenge(inc.match_id, true); }catch(e){}
    };
    box.querySelector(".gcb-dismiss").onclick = () => hideGlobalChallengeBanner();
}

function hideGlobalChallengeBanner(){
    let box = document.getElementById("global-challenge-banner");
    if(box) box.classList.add("hidden");
}

