async function setMyGlowColor(characterId, color){

    let player_token = localStorage.getItem("player_token");

    if(!player_token){

        alert("ط·آ¸ط¸آ¹ط·آ·ط¢آ¬ط·آ·ط¢آ¨ ط·آ·ط¹آ¾ط·آ·ط¢آ³ط·آ·ط¢آ¬ط·آ¸ط¸آ¹ط·آ¸أ¢â‚¬â€چ ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ¯ط·آ·ط¢آ®ط·آ¸ط«â€ ط·آ¸أ¢â‚¬â€چ");

        return;

    }

    let {error} =

    await supabaseClient
    .rpc("player_set_glow_color", {

        p_token: player_token,

        p_character_id: characterId,

        p_color: color

    });

    if(error){

        alert(error.message);

    }

    loadCollection();

}
