    if(totalEl) totalEl.textContent = "ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ¸أ¢â‚¬آ¦ط·آ·ط¢آ¬ط·آ¸أ¢â‚¬آ¦ط·آ¸ط«â€ ط·آ·ط¢آ¹: " + (upgradeSplit.hp + upgradeSplit.atk) + " / 200";
