function splitAdjustHp(delta){
    let newHp = upgradeSplit.hp + delta;
    // ط·آ¸ط¦â€™ط·آ¸أ¢â‚¬â€چ ط·آ·ط¢آµط·آ¸ط¸آ¾ط·آ·ط¢آ© ط·آ·ط¢آ¨ط·آ¸ط¸آ¹ط·آ¸أ¢â‚¬آ  50 ط·آ¸ط«â€ 150 ط·آ·ط¢آ¨ط·آ·ط¢آ®ط·آ·ط¢آ·ط·آ¸ط«â€ ط·آ·ط¢آ§ط·آ·ط¹آ¾ 50ط·آ·ط¥â€™ ط·آ¸ط«â€ ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ¸أ¢â‚¬آ¦ط·آ·ط¢آ¬ط·آ¸أ¢â‚¬آ¦ط·آ¸ط«â€ ط·آ·ط¢آ¹ ط·آ·ط¢آ«ط·آ·ط¢آ§ط·آ·ط¢آ¨ط·آ·ط¹آ¾ 200
    if(newHp < 50) newHp = 50;
    if(newHp > 150) newHp = 150;
    upgradeSplit.hp = newHp;
    upgradeSplit.atk = 200 - newHp;
    updateSplitUI();
}

