// الموافقة على شخصية مطلوبة بالذكاء الاصطناعي
async function approveCharacter(characterId){
    let admin_token = localStorage.getItem("admin_token");
    if(!admin_token){ alert("يجب تسجيل الدخول كأدمن أولاً."); return; }
    let { error } = await supabaseClient.rpc("admin_approve_character", {
        p_admin_token: admin_token,
        p_character_id: characterId
    });
    if(error){ alert(error.message); return; }
    alert("تم قبول الشخصية وإرسالها للاعب");
    clearCharacterSkillCache();
    loadAdminMyCharacters();
    updateSkillOrderBadge();
}

// رفض شخصية مطلوبة بالذكاء الاصطناعي
async function rejectCharacter(characterId){
    let admin_token = localStorage.getItem("admin_token");
    if(!admin_token){ alert("يجب تسجيل الدخول كأدمن أولاً."); return; }
    let { error } = await supabaseClient.rpc("admin_reject_character", {
        p_admin_token: admin_token,
        p_character_id: characterId
    });
    if(error){ alert(error.message); return; }
    alert("تم رفض الطلب");
    clearCharacterSkillCache();
    loadAdminMyCharacters();
    updateSkillOrderBadge();
}

function clearCharacterSkillCache(){
    try{
        let keysToRemove = [];
        for(let i = 0; i < localStorage.length; i++){
            let k = localStorage.key(i);
            if(k && k.indexOf("character_skills_") !== -1) keysToRemove.push(k);
        }
        keysToRemove.forEach(k => localStorage.removeItem(k));
    }catch(e){ /* تجاهل */ }
}


