// ط·آ¸أ¢â‚¬آ ط·آ·ط¢آ³ط·آ·ط¢آ¨ط·آ·ط¢آ© ط·آ·ط¢آ£ط·آ·ط¢آ¨ط·آ·ط¢آ¹ط·آ·ط¢آ§ط·آ·ط¢آ¯ ط·آ¸أ¢â‚¬آ¦ط·آ·ط¢آ­ط·آ·ط¢آ¯ط·آ·ط¢آ¯ط·آ·ط¢آ©. ط·آ·ط¢آ¹ط·آ¸أ¢â‚¬آ ط·آ·ط¢آ¯ ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ·ط¹آ¾ط·آ·ط¢آ£ط·آ¸ط¦â€™ط·آ¸ط¸آ¹ط·آ·ط¢آ¯ ط·آ·ط¹آ¾ط·آ¸ط¹ث†ط·آ·ط¢آ±ط·آ·ط¢آ¬ط·آ·ط¢آ¹ ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ·ط¢آµط·آ¸ط«â€ ط·آ·ط¢آ±ط·آ·ط¢آ© ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ¸أ¢â‚¬آ¦ط·آ¸أ¢â‚¬ع‘ط·آ·ط¹آ¾ط·آ·ط¢آµط·آ¸ط¹ع©ط·آ¸أ¢â‚¬ع©ط·آ·ط¢آ© ط·آ¸ط¦â€™ط·آ¸أ¢â€ڑآ¬ Blob.

let _cropState = null;

function openCropModal(file, options){

    options = options || {};

    return new Promise(function(resolve, reject){

        let url = URL.createObjectURL(file);

        let img = new Image();

        img.onload = function(){

            // ط·آ·ط¢آ£ط·آ·ط¢آ¨ط·آ·ط¢آ¹ط·آ·ط¢آ§ط·آ·ط¢آ¯ ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ´ط·آ·ط¢آ§ط·آ·ط¢آ´ط·آ·ط¢آ© ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ¸ط¸آ¾ط·آ·ط¢آ¹ط·آ¸أ¢â‚¬â€چط·آ¸ط¸آ¹ط·آ·ط¢آ© ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ¹ط·آ·ط¢آ±ط·آ·ط¢آ¶ ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ¸أ¢â‚¬آ ط·آ·ط¢آ§ط·آ¸ط¸آ¾ط·آ·ط¢آ°ط·آ·ط¢آ©
            let viewW = Math.min(window.innerWidth - 40, 440);

            let viewH = Math.min(window.innerHeight - 180, 480);

            // ط·آ¸أ¢â‚¬آ ط·آ·ط¢آ³ط·آ·ط¢آ¨ط·آ·ط¢آ© ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ£ط·آ·ط¢آ¨ط·آ·ط¢آ¹ط·آ·ط¢آ§ط·آ·ط¢آ¯ ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ¸أ¢â‚¬آ¦ط·آ·ط¢آ·ط·آ¸أ¢â‚¬â€چط·آ¸ط«â€ ط·آ·ط¢آ¨ط·آ·ط¢آ© ط·آ¸أ¢â‚¬â€چط·آ¸أ¢â‚¬â€چط·آ¸أ¢â‚¬ع‘ط·آ·ط¢آµ (ط·آ·ط¢آ§ط·آ¸ط¸آ¾ط·آ·ط¹آ¾ط·آ·ط¢آ±ط·آ·ط¢آ§ط·آ·ط¢آ¶ط·آ¸ط¸آ¹ 1:1 ط·آ¸أ¢â‚¬آ¦ط·آ·ط¢آ±ط·آ·ط¢آ¨ط·آ¸أ¢â‚¬ع©ط·آ·ط¢آ¹)
            let aspect = options.aspectRatio || 1;

            let cropW = 220;

            let cropH = cropW / aspect;

            if(cropH > viewH - 120){ cropH = viewH - 120; cropW = cropH * aspect; }

            // ط·آ¸أ¢â‚¬آ¦ط·آ¸أ¢â‚¬ع‘ط·آ¸ط¸آ¹ط·آ·ط¢آ§ط·آ·ط¢آ³ ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ¹ط·آ·ط¢آ±ط·آ·ط¢آ¶ ط·آ·ط¢آ¯ط·آ·ط¢آ§ط·آ·ط¢آ®ط·آ¸أ¢â‚¬â€چ ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ¸أ¢â‚¬آ ط·آ·ط¢آ§ط·آ¸ط¸آ¾ط·آ·ط¢آ°ط·آ·ط¢آ© ط·آ¸أ¢â‚¬آ¦ط·آ·ط¢آ¹ ط·آ¸أ¢â‚¬آ¦ط·آ·ط¢آ³ط·آ·ط¢آ§ط·آ·ط¢آ­ط·آ·ط¢آ© ط·آ·ط¢آ¨ط·آ¸ط¸آ¹ط·آ·ط¢آ¶ط·آ·ط¢آ§ط·آ·ط·إ’ (ط·آ·ط¢آ¹ط·آ·ط¢آ±ط·آ·ط¢آ¶) ط·آ¸ط«â€ ط·آ¸أ¢â‚¬آ¦ط·آ·ط¢آ³ط·آ·ط¢آ§ط·آ·ط¢آ­ط·آ·ط¢آ© ط·آ·ط¢آ¨ط·آ¸ط¸آ¹ط·آ·ط¢آ¶ط·آ·ط¢آ§ط·آ·ط·إ’ (ط·آ·ط¢آ§ط·آ·ط¢آ±ط·آ·ط¹آ¾ط·آ¸ط¸آ¾ط·آ·ط¢آ§ط·آ·ط¢آ¹)
            let fitScale = Math.min((viewW - 24) / img.width, (viewH - 24) / img.height);

            let dispW = Math.round(img.width * fitScale);

            let dispH = Math.round(img.height * fitScale);

            _cropState = {
                img: img,
                file: file,
                dispW: dispW,
                dispH: dispH,
                scale: fitScale,
                aspect: aspect,
                cropW: cropW,
                cropH: cropH,
                cropX: Math.round((dispW - cropW) / 2),
                cropY: Math.round((dispH - cropH) / 2),
                imgOffX: 0,
                imgOffY: 0,
                zoom: 1,
                resolve: resolve,
                reject: reject
            };

            buildCropModal(_cropState);

            URL.revokeObjectURL(url);

        };

        img.onerror = function(){ reject(new Error("ط·آ·ط¹آ¾ط·آ·ط¢آ¹ط·آ·ط¢آ°ط·آ¸أ¢â‚¬ع©ط·آ·ط¢آ± ط·آ¸أ¢â‚¬ع‘ط·آ·ط¢آ±ط·آ·ط¢آ§ط·آ·ط·إ’ط·آ·ط¢آ© ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ·ط¢آµط·آ¸ط«â€ ط·آ·ط¢آ±ط·آ·ط¢آ©")); };

        img.src = url;

    });

}


