                "<select id=\"crop-aspect\">" +
                    "<option value=\"1\">ط·آ¸أ¢â‚¬آ¦ط·آ·ط¢آ±ط·آ·ط¢آ¨ط·آ¸أ¢â‚¬ع©ط·آ·ط¢آ¹ 1:1</option>" +
                    "<option value=\"1.25\">4:5 (ط·آ·ط¢آ¹ط·آ¸أ¢â‚¬آ¦ط·آ¸ط«â€ ط·آ·ط¢آ¯ط·آ¸ط¸آ¹)</option>" +
                    "<option value=\"0.75\">3:4 (ط·آ·ط¢آ±ط·آ·ط¢آ£ط·آ·ط¢آ³ط·آ¸ط¸آ¹)</option>" +
                    "<option value=\"1.78\">16:9 (ط·آ·ط¢آ¹ط·آ·ط¢آ±ط·آ¸ط¸آ¹ط·آ·ط¢آ¶)</option>" +
                "</select>" +
                "<button id=\"crop-zoom-in\">+ ط·آ·ط¹آ¾ط·آ¸ط¦â€™ط·آ·ط¢آ¨ط·آ¸ط¸آ¹ط·آ·ط¢آ±</button>" +
                "<button id=\"crop-zoom-out\">ط£آ¢ط«â€ أ¢â‚¬â„¢ ط·آ·ط¹آ¾ط·آ·ط¢آµط·آ·ط·â€؛ط·آ¸ط¸آ¹ط·آ·ط¢آ±</button>" +
            "</div>" +
            "<div class=\"crop-actions\">" +
                "<button id=\"crop-confirm\" class=\"crop-confirm-btn\">ط·آ·ط¹آ¾ط·آ·ط¢آ£ط·آ¸ط¦â€™ط·آ¸ط¸آ¹ط·آ·ط¢آ¯</button>" +
                "<button id=\"crop-cancel\" class=\"crop-cancel-btn\">ط·آ·ط¢آ¥ط·آ¸أ¢â‚¬â€چط·آ·ط·â€؛ط·آ·ط¢آ§ط·آ·ط·إ’</button>" +
            "</div>" +
        "</div>";

    document.body.appendChild(modal);

    let stage = document.getElementById("crop-stage");

    let canvas = document.getElementById("crop-canvas");

    canvas.width = state.dispW;

    canvas.height = state.dispH;

    stage.style.width = state.dispW + "px";

