async function loadCharacterSkillsForAdmin(character_id){

    let {data, error} =

    await supabaseClient
    .from("character_skills")
    .select(`

        slot,

        skills (*)

    `)
    .eq("character_id", character_id)
    .order("slot");

    if(error || !data) return [];

    return data
    .filter(row => row.skills)
    .map(row => ({...row.skills, slot: row.slot}));

}


