async function saveSkillPageBackground(characterId, pageIndex){

    let input = document.getElementById("page-bg-" + pageIndex);

    let url = input ? input.value.trim() : "";

    let admin_token = localStorage.getItem("admin_token");

    let {error} =

    await supabaseClient
    .rpc("admin_set_character_skill_page_background", {

        p_admin_token: admin_token,

        p_character_id: characterId,

        p_page_index: pageIndex,

        p_image_url: url

    });

    let status = document.getElementById("page-bg-status-" + pageIndex);

    if(error){

        if(status) status.textContent = "";

        alert(error.message || "ط·آ·ط¹آ¾ط·آ·ط¢آ¹ط·آ·ط¢آ°ط·آ·ط¢آ± ط·آ·ط¢آ­ط·آ¸ط¸آ¾ط·آ·ط¢آ¸ ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ®ط·آ¸أ¢â‚¬â€چط·آ¸ط¸آ¾ط·آ¸ط¸آ¹ط·آ·ط¢آ©");

        return;

    }

    if(status) status.textContent = url ? "ط£آ¢ط¥â€œأ¢â‚¬إ“ ط·آ·ط¢آ­ط·آ¸ط¹ث†ط·آ¸ط¸آ¾ط·آ·ط¢آ¸ط·آ·ط¹آ¾ ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ®ط·آ¸أ¢â‚¬â€چط·آ¸ط¸آ¾ط·آ¸ط¸آ¹ط·آ·ط¢آ©" : "ط£آ¢ط¥â€œأ¢â‚¬إ“ ط·آ·ط¢آ£ط·آ¸ط¹ث†ط·آ·ط¢آ²ط·آ¸ط¸آ¹ط·آ¸أ¢â‚¬â€چط·آ·ط¹آ¾ ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ®ط·آ¸أ¢â‚¬â€چط·آ¸ط¸آ¾ط·آ¸ط¸آ¹ط·آ·ط¢آ©";

    GameCache.clear("skill_page_bgs_" + characterId);

}


async function clearSkillPageBackground(characterId, pageIndex){

    let input = document.getElementById("page-bg-" + pageIndex);

    if(input) input.value = "";

    await saveSkillPageBackground(characterId, pageIndex);

}


