async function saveSkillPageScale(characterId, pageIndex){

    let input = document.getElementById("page-scale-" + pageIndex);

    let scale = input ? parseFloat(input.value) : 1;

    if(isNaN(scale) || scale <= 0) scale = 1;

    if(scale > 3) scale = 3;

    if(scale < 0.5) scale = 0.5;

    if(input) input.value = scale;

    let admin_token = localStorage.getItem("admin_token");

    let {error} =

    await supabaseClient
    .rpc("admin_set_character_skill_page_scale", {

        p_admin_token: admin_token,

        p_character_id: characterId,

        p_page_index: pageIndex,

        p_skill_scale: scale

    });

    let status = document.getElementById("page-bg-status-" + pageIndex);

    if(error){

        if(status) status.textContent = "";

        alert(error.message || "ط·آ·ط¹آ¾ط·آ·ط¢آ¹ط·آ·ط¢آ°ط·آ·ط¢آ± ط·آ·ط¢آ­ط·آ¸ط¸آ¾ط·آ·ط¢آ¸ ط·آ·ط¢آ­ط·آ·ط¢آ¬ط·آ¸أ¢â‚¬آ¦ ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ¸أ¢â‚¬آ¦ط·آ¸أ¢â‚¬طŒط·آ·ط¢آ§ط·آ·ط¢آ±ط·آ·ط¢آ§ط·آ·ط¹آ¾");

        return;

    }

    if(status) status.textContent = "ط£آ¢ط¥â€œأ¢â‚¬إ“ ط·آ·ط¢آ­ط·آ¸ط¹ث†ط·آ¸ط¸آ¾ط·آ·ط¢آ¸ ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ­ط·آ·ط¢آ¬ط·آ¸أ¢â‚¬آ¦";

    GameCache.clear("skill_page_bgs_" + characterId);

}


