// ط·آ¸ط¸آ¹ط·آ·ط¢آ­ط·آ¸ط«â€ ط·آ¸أ¢â‚¬ع©ط·آ¸أ¢â‚¬â€چ ط·آ·ط¢آ§ط·آ·ط¢آ®ط·آ·ط¹آ¾ط·آ¸ط¸آ¹ط·آ·ط¢آ§ط·آ·ط¢آ± ط·آ¸أ¢â‚¬آ ط·آ¸ط«â€ ط·آ·ط¢آ¹ ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ¸أ¢â‚¬آ¦ط·آ¸أ¢â‚¬طŒط·آ·ط¢آ§ط·آ·ط¢آ±ط·آ·ط¢آ© ط·آ¸ط¸آ¾ط·آ¸ط¸آ¹ ط·آ¸أ¢â‚¬ع‘ط·آ¸ط«â€ ط·آ·ط¢آ§ط·آ·ط¢آ¦ط·آ¸أ¢â‚¬آ¦ ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ¸أ¢â‚¬آ ط·آ¸ط«â€ ط·آ·ط¢آ¹ (ط·آ·ط¢آ¥ط·آ·ط¢آ¶ط·آ·ط¢آ§ط·آ¸ط¸آ¾ط·آ·ط¢آ©/ط·آ·ط¹آ¾ط·آ·ط¢آ¹ط·آ·ط¢آ¯ط·آ¸ط¸آ¹ط·آ¸أ¢â‚¬â€چ) ط·آ·ط¢آ¥ط·آ¸أ¢â‚¬â€چط·آ¸أ¢â‚¬آ° ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ­ط·آ¸أ¢â‚¬ع‘ط·آ¸ط«â€ ط·آ¸أ¢â‚¬â€چ ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ¸ط¸آ¾ط·آ·ط¢آ¹ط·آ¸أ¢â‚¬â€چط·آ¸ط¸آ¹ط·آ·ط¢آ©
// type/effect/unblockable ط·آ¸ط¦â€™ط·آ¸أ¢â‚¬آ¦ط·آ·ط¢آ§ ط·آ¸أ¢â‚¬طŒط·آ¸ط¸آ¹ ط·آ¸أ¢â‚¬آ¦ط·آ·ط¢آ®ط·آ·ط¢آ²ط·آ¸أ¢â‚¬ع©ط·آ¸أ¢â‚¬آ ط·آ·ط¢آ© ط·آ¸ط¸آ¾ط·آ¸ط¸آ¹ ط·آ·ط¢آ¬ط·آ·ط¢آ¯ط·آ¸ط«â€ ط·آ¸أ¢â‚¬â€چ skills
function skillTypeChoiceToFields(typeChoice){

    let type = "attack";

    let effect = null;

    let unblockable = false;

    if(typeChoice === "defense"){

        type = "defense";

    } else if(typeChoice === "special"){

        type = "special";

    } else if(typeChoice === "steal"){

        type = "special";

        effect = "steal";

    } else if(typeChoice === "copy"){

        type = "special";

        effect = "copy";

    } else if(typeChoice === "control"){

        type = "special";

        effect = "control";

    } else if(typeChoice === "unblockable"){

        type = "special";

        unblockable = true;

    } else if(typeChoice === "freeze"){

        type = "special";

        effect = "freeze";

    } else if(typeChoice === "lifesteal"){

        type = "special";

        effect = "lifesteal";

    } else if(typeChoice === "reflect"){

        type = "special";

        effect = "reflect";

    } else if(typeChoice === "unblockable_reflect"){

        type = "special";

        effect = "reflect";

        unblockable = true;

    } else if(typeChoice === "seal"){

        type = "special";

        effect = "seal";

    } else if(typeChoice === "unseal"){

        type = "special";

        effect = "unseal";

    } else if(typeChoice === "consecutive_turns"){

        type = "special";

        effect = "consecutive_turns";

    } else if(typeChoice === "absorb_atk"){

        type = "special";

        effect = "absorb_atk";

    } else if(typeChoice === "absorb_hp"){

        type = "special";

        effect = "absorb_hp";

    } else if(typeChoice === "hp_boost"){

        type = "special";

        effect = "hp_boost";

    } else if(typeChoice === "atk_boost"){

        type = "special";

        effect = "atk_boost";

    } else if(typeChoice === "poison"){

        type = "special";

        effect = "poison";

    } else if(typeChoice === "delay_cooldown"){

        type = "special";

        effect = "delay_cooldown";

    } else if(typeChoice === "shadow"){

        type = "special";

        effect = "shadow";

    }

    return {type, effect, unblockable};

}


// ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ§ط·آ·ط¹آ¾ط·آ·ط¢آ¬ط·آ·ط¢آ§ط·آ¸أ¢â‚¬طŒ ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ¸أ¢â‚¬آ¦ط·آ·ط¢آ¹ط·آ·ط¢آ§ط·آ¸ط¦â€™ط·آ·ط¢آ³: ط·آ¸أ¢â‚¬آ¦ط·آ¸أ¢â‚¬آ  ط·آ¸ط¦â€™ط·آ·ط¢آ§ط·آ·ط¢آ¦ط·آ¸أ¢â‚¬آ  ط·آ¸أ¢â‚¬آ¦ط·آ¸أ¢â‚¬طŒط·آ·ط¢آ§ط·آ·ط¢آ±ط·آ·ط¢آ© (ط·آ¸ط¦â€™ط·آ¸أ¢â‚¬آ¦ط·آ·ط¢آ§ ط·آ¸ط¸آ¹ط·آ¸ط¹ث†ط·آ¸أ¢â‚¬ع‘ط·آ·ط¢آ±ط·آ·ط¢آ£ ط·آ¸أ¢â‚¬آ¦ط·آ¸أ¢â‚¬آ  ط·آ¸أ¢â‚¬ع‘ط·آ·ط¢آ§ط·آ·ط¢آ¹ط·آ·ط¢آ¯ط·آ·ط¢آ© ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ¨ط·آ¸ط¸آ¹ط·آ·ط¢آ§ط·آ¸أ¢â‚¬آ ط·آ·ط¢آ§ط·آ·ط¹آ¾) ط·آ·ط¢آ¥ط·آ¸أ¢â‚¬â€چط·آ¸أ¢â‚¬آ° ط·آ¸أ¢â‚¬ع‘ط·آ¸ط¸آ¹ط·آ¸أ¢â‚¬آ¦ط·آ·ط¢آ©
// ط·آ¸أ¢â‚¬ع‘ط·آ·ط¢آ§ط·آ·ط¢آ¦ط·آ¸أ¢â‚¬آ¦ط·آ·ط¢آ© ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ¸أ¢â‚¬آ ط·آ¸ط«â€ ط·آ·ط¢آ¹ط·آ·ط¥â€™ ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ¹ط·آ·ط¢آ±ط·آ·ط¢آ¶ ط·آ¸أ¢â‚¬ع‘ط·آ·ط¢آ§ط·آ·ط¢آ¦ط·آ¸أ¢â‚¬آ¦ط·آ·ط¢آ© ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ¸أ¢â‚¬آ ط·آ¸ط«â€ ط·آ·ط¢آ¹ ط·آ¸ط¸آ¾ط·آ¸ط¸آ¹ ط·آ¸أ¢â‚¬آ ط·آ¸أ¢â‚¬آ¦ط·آ¸ط«â€ ط·آ·ط¢آ°ط·آ·ط¢آ¬ ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ·ط¹آ¾ط·آ·ط¢آ¹ط·آ·ط¢آ¯ط·آ¸ط¸آ¹ط·آ¸أ¢â‚¬â€چ ط·آ·ط¢آ¹ط·آ¸أ¢â‚¬â€چط·آ¸أ¢â‚¬آ° ط·آ¸أ¢â‚¬ع‘ط·آ¸ط¸آ¹ط·آ¸أ¢â‚¬آ¦ط·آ·ط¹آ¾ط·آ¸أ¢â‚¬طŒط·آ·ط¢آ§ ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ­ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ¸ط¸آ¹ط·آ·ط¢آ©
function skillFieldsToTypeChoice(skill){

    if(skill.unblockable && skill.effect === "reflect") return "unblockable_reflect";

    if(skill.unblockable) return "unblockable";

    if(skill.effect === "steal") return "steal";

    if(skill.effect === "copy") return "copy";

    if(skill.effect === "control") return "control";

    if(skill.effect === "freeze") return "freeze";

    if(skill.effect === "lifesteal") return "lifesteal";

    if(skill.effect === "reflect") return "reflect";

    if(skill.effect === "seal") return "seal";

    if(skill.effect === "unseal") return "unseal";

    if(skill.effect === "consecutive_turns") return "consecutive_turns";

    if(skill.effect === "absorb_atk") return "absorb_atk";

    if(skill.effect === "absorb_hp") return "absorb_hp";

    if(skill.effect === "hp_boost") return "hp_boost";

    if(skill.effect === "atk_boost") return "atk_boost";

    if(skill.effect === "poison") return "poison";

    if(skill.effect === "delay_cooldown") return "delay_cooldown";

    if(skill.effect === "shadow") return "shadow";

    if(skill.type === "defense") return "defense";

    if(skill.type === "special") return "special";

    return "attack";

}


