function renderAdminPotionCards(list, emptyMessage){
    if(!list || list.length === 0) return '<p class="admin-hint">' + escapeAttr(emptyMessage) + '</p>';
    return list.map(p => {
        let stock = p.infinite ? "ط£آ¢أ¢â€‍آ¢ط¢آ¾ط£آ¯ط¢آ¸ط¹ث† ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ§ ط·آ¸أ¢â‚¬آ¦ط·آ·ط¢آ­ط·آ·ط¢آ¯ط·آ¸ط«â€ ط·آ·ط¢آ¯" : ("ط¸â€¹ط¹ط›أ¢â‚¬إ“ط¢آ¦ " + (p.stock == null ? 0 : p.stock) + " ط·آ·ط¢آ¬ط·آ·ط¢آ±ط·آ·ط¢آ¹ط·آ·ط¢آ©");
        let sold = (p.sold || 0) > 0 ? (" ط·آ¢ط¢آ· ط·آ¸أ¢â‚¬آ¦ط·آ¸ط¹ث†ط·آ¸أ¢â‚¬â€چط·آ¸ط¦â€™ " + p.sold) : "";
        let eff = potionEffectTypeLabel(p.effect_type, p.effect_value);
        // ط·آ·ط¢آ£ط·آ·ط¢آ¶ط·آ¸ط¸آ¾ ط·آ¸أ¢â‚¬آ ط·آ¸ط«â€ ط·آ·ط¢آ¹ ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ¸أ¢â‚¬آ¦ط·آ¸أ¢â‚¬طŒط·آ·ط¢آ§ط·آ·ط¢آ±ط·آ·ط¢آ© ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ¸أ¢â‚¬آ¦ط·آ·ط¢آ¯ط·آ¸أ¢â‚¬آ¦ط·آ·ط¢آ¬ط·آ·ط¢آ© ط·آ¸أ¢â‚¬â€چط·آ¸ط«â€  ط·آ¸ط«â€ ط·آ¸ط¹ث†ط·آ·ط¢آ¬ط·آ·ط¢آ¯ط·آ·ط¹آ¾
        if(p.effect_type === "skill"){
            if(p.effect_skill_type){
                eff += " (ط·آ¢ط¢آ«" + potionSkillTypeLabel(p.effect_skill_type) + "ط·آ¢ط¢آ»)";
            }
        }
        return `
            <div class="admin-card" style="margin-bottom:8px; padding:12px; border-left:4px solid ${escapeAttr(p.glow_color || '#22c55e')};">
                <div style="display:flex; align-items:center; gap:10px; flex-wrap:wrap; justify-content:space-between;">
                    <div style="display:flex; align-items:center; gap:10px;">
                        ${p.image ? `<img src="${escapeAttr(p.image)}" style="width:44px;height:44px;object-fit:cover;border-radius:8px;">` : `<div style="width:44px;height:44px;display:flex;align-items:center;justify-content:center;background:rgba(255,255,255,0.05);border-radius:8px;">ط¸â€¹ط¹ط›ط¢آ§ط¹آ¾</div>`}
                        <div>
                            <strong>${escapeAttr(p.name || "ط·آ·ط¢آ¨ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ§ ط·آ·ط¢آ§ط·آ·ط¢آ³ط·آ¸أ¢â‚¬آ¦")}</strong>
                            <div class="admin-hint" style="font-size:12px;">ط¸â€¹ط¹ط›أ¢â‚¬â„¢ط¢آ° ${p.price || 0} ط¸â€¹ط¹ط›ط¹آ¾أ¢â€‍آ¢ ط·آ¢ط¢آ· ${escapeAttr(stock)}${sold}<br>${escapeAttr(eff)}</div>
                        </div>
                    </div>
                    <div style="display:flex; gap:6px; flex-wrap:wrap;">
                        <button class="admin-btn" onclick="openEditPotionModal('${p.id}')">ط£آ¢ط¥â€œط¹ث†ط£آ¯ط¢آ¸ط¹ث† ط·آ·ط¹آ¾ط·آ·ط¢آ­ط·آ·ط¢آ±ط·آ¸ط¸آ¹ط·آ·ط¢آ±</button>
                        <button class="admin-btn" onclick="deletePotion('${p.id}')">ط¸â€¹ط¹ط›أ¢â‚¬â€‌أ¢â‚¬ع©ط£آ¯ط¢آ¸ط¹ث† ط·آ·ط¢آ­ط·آ·ط¢آ°ط·آ¸ط¸آ¾</button>
                    </div>
                </div>
            </div>`;
    }).join("");
}

