function collectWeaponSkill(id){
    let val = sel => (document.getElementById(sel) || {}).value;
    let num = sel => Number(val(sel)) || 0;
    let obj = { id };
    obj.name = val("wskill-name-" + id);
    obj.typeChoice = val("wskill-type-" + id);
    let f = skillTypeChoiceToFields(obj.typeChoice);
    obj.type = f.type;
    obj.effect = f.effect;
    obj.unblockable = f.unblockable;
    obj.damage = num("wskill-damage-" + id);
    obj.cooldown = num("wskill-cooldown-" + id);
    obj.description = val("wskill-desc-" + id);
    let paramsRaw = val("wskill-params-" + id);
    try{ obj.params = paramsRaw.trim() ? JSON.parse(paramsRaw) : {}; }catch(e){ obj.params = {}; }
    obj.color = val("wskill-color-" + id) || "#3b82ff";
    obj.stroke_color = val("wskill-stroke-color-" + id);
    obj.stroke_width = num("wskill-stroke-width-" + id);
    return obj;
}


async function saveWeaponSkillEdit(skillId){
    let wId = currentEditWeaponId;
    let s = collectWeaponSkill(skillId);
    let admin_token = localStorage.getItem("admin_token");
    let {error} = await supabaseClient.rpc("admin_update_weapon_skill", {
        p_admin_token: admin_token, p_weapon_id: wId, p_skill_id: skillId,
        p_name: s.name || "", p_type: s.type || "attack", p_damage: s.damage || 0,
        p_cooldown: s.cooldown || 0, p_effect: s.effect, p_unblockable: !!s.unblockable,
        p_description: s.description, p_color: s.color || "#3b82ff",
        p_params: s.params || {}, p_stroke_color: s.stroke_color, p_stroke_width: s.stroke_width || 0
    });
    if(error){ alert(error.message); return; }
    alert("ط·آ·ط¹آ¾ط·آ¸أ¢â‚¬آ¦ ط·آ·ط¢آ­ط·آ¸ط¸آ¾ط·آ·ط¢آ¸ ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ¸أ¢â‚¬آ¦ط·آ¸أ¢â‚¬طŒط·آ·ط¢آ§ط·آ·ط¢آ±ط·آ·ط¢آ©");
}


async function addWeaponSkill(wId){
    let name = (document.getElementById("new-wskill-name") || {}).value; name = name ? name.trim() : "";
    if(name === ""){ alert("ط·آ·ط¢آ§ط·آ¸ط¦â€™ط·آ·ط¹آ¾ط·آ·ط¢آ¨ ط·آ·ط¢آ§ط·آ·ط¢آ³ط·آ¸أ¢â‚¬آ¦ ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ¸أ¢â‚¬آ¦ط·آ¸أ¢â‚¬طŒط·آ·ط¢آ§ط·آ·ط¢آ±ط·آ·ط¢آ©"); return; }
    let typeChoice = document.getElementById("new-wskill-type").value || "attack";
    let f = skillTypeChoiceToFields(typeChoice);
    let color = (document.getElementById("new-wskill-color") || {}).value || "#3b82ff";
    let strokeColor = (document.getElementById("new-wskill-stroke-color") || {}).value;
    let strokeWidth = Number((document.getElementById("new-wskill-stroke-width") || {}).value) || 0;
    let paramsRaw = (document.getElementById("new-wskill-params") || {}).value || "";
    let admin_token = localStorage.getItem("admin_token");
    let {error} = await supabaseClient.rpc("admin_add_weapon_skill", {
        p_admin_token: admin_token, p_weapon_id: wId, p_name: name,
        p_type: f.type || "attack", p_damage: Number(document.getElementById("new-wskill-damage").value) || 0,
        p_cooldown: Number(document.getElementById("new-wskill-cooldown").value) || 0,
        p_effect: f.effect, p_unblockable: !!f.unblockable,
        p_description: document.getElementById("new-wskill-desc").value.trim() || null,
        p_color: color, p_params: (() => { try{ return paramsRaw.trim() ? JSON.parse(paramsRaw) : {}; }catch(e){ return {}; } })(),
        p_stroke_color: strokeColor, p_stroke_width: strokeWidth
    });
    if(error){ alert(error.message); return; }
    alert("ط·آ·ط¹آ¾ط·آ¸أ¢â‚¬آ¦ط·آ·ط¹آ¾ ط·آ·ط¢آ¥ط·آ·ط¢آ¶ط·آ·ط¢آ§ط·آ¸ط¸آ¾ط·آ·ط¢آ© ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ¸أ¢â‚¬آ¦ط·آ¸أ¢â‚¬طŒط·آ·ط¢آ§ط·آ·ط¢آ±ط·آ·ط¢آ©");
    document.getElementById("weapon-edit-modal").remove();
    openEditWeaponModal(wId);
}

async function removeWeaponSkill(wId, skillId){
    let admin_token = localStorage.getItem("admin_token");
    let {error} = await supabaseClient.rpc("admin_remove_weapon_skill", { p_admin_token: admin_token, p_weapon_id: wId, p_skill_id: skillId });
    if(error){ alert(error.message); return; }
    document.getElementById("weapon-edit-modal").remove();
    openEditWeaponModal(wId);
}

async function saveWeaponEdit(wId){
    let name = document.getElementById("edit-weapon-name").value.trim();
    if(name === ""){ alert("ط·آ·ط¢آ§ط·آ¸ط¦â€™ط·آ·ط¹آ¾ط·آ·ط¢آ¨ ط·آ·ط¢آ§ط·آ·ط¢آ³ط·آ¸أ¢â‚¬آ¦ ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ³ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ§ط·آ·ط¢آ­"); return; }
    let admin_token = localStorage.getItem("admin_token");
    let {error} = await supabaseClient.rpc("admin_save_weapon", {
        p_admin_token: admin_token, p_weapon_id: wId, p_name: name,
        p_description: document.getElementById("edit-weapon-description").value.trim(),
        p_image: document.getElementById("edit-weapon-image").value.trim(),
        p_skill_card_image: document.getElementById("edit-weapon-skillcard").value.trim(),
        p_price: Number(document.getElementById("edit-weapon-price").value) || 0,
        p_max_durability: Number(document.getElementById("edit-weapon-durability").value) || 0,
        p_stock: Number(document.getElementById("edit-weapon-stock").value) || 0,
        p_infinite: document.getElementById("edit-weapon-infinite").checked,
        p_glow_color: document.getElementById("edit-weapon-glow-color").value || "#e8b93f"
    });
    if(error){ alert(error.message); return; }
    alert("ط·آ·ط¹آ¾ط·آ¸أ¢â‚¬آ¦ ط·آ·ط¢آ­ط·آ¸ط¸آ¾ط·آ·ط¢آ¸ ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ³ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ§ط·آ·ط¢آ­");
    document.getElementById("weapon-edit-modal").remove();
    loadAdminWeapons();
}


