function refreshGame(){


    updatePlayerInfo();


    let screen =
    document.querySelector(
        ".screen.active"
    );



    if(!screen)
    return;




    if(screen.id === "collection-screen"){


        loadCollection();


    }




    if(screen.id === "character-profile-screen"){


        loadCharacterProfile();


    }




    if(screen.id === "upgrade-screen"){


        loadUpgradeScreen();


    }



}







