            // window.open(url, "_system", ...) ط·آ¸أ¢â‚¬طŒط·آ¸ط«â€  ط·آ·ط¢آ£ط·آ·ط¢آ³ط·آ¸أ¢â‚¬â€چط·آ¸ط«â€ ط·آ·ط¢آ¨ Cordova ط·آ¸ط«â€ ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ§ ط·آ¸ط¸آ¹ط·آ·ط¢آ¹ط·آ¸أ¢â‚¬آ¦ط·آ¸أ¢â‚¬â€چ ط·آ¸ط¸آ¾ط·آ¸ط¸آ¹ Capacitor.
            var url = manifest.downloadUrl;
