//   admin-char-skills-editor        (ط·آ·ط¢آ´ط·آ·ط¢آ®ط·آ·ط¢آµط·آ¸ط¸آ¹ط·آ·ط¢آ§ط·آ·ط¹آ¾ / ط·آ¸ط«â€ ط·آ·ط¢آ­ط·آ¸ط«â€ ط·آ·ط¢آ´)
//   admin-weapon-skills-editor      (ط·آ·ط¢آ£ط·آ·ط¢آ³ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ­ط·آ·ط¢آ©)
//   admin-companion-skills-editor   (ط·آ¸أ¢â‚¬آ¦ط·آ·ط¢آ±ط·آ·ط¢آ§ط·آ¸ط¸آ¾ط·آ¸أ¢â‚¬ع‘ط·آ¸ط«â€ ط·آ¸أ¢â‚¬آ )
function addSkillEditorRow(editorId, skill){
    const editor = document.getElementById(editorId);
    if(!editor) return;
    const empty = editor.querySelector(".admin-skills-empty");
    if(empty) empty.remove();
    const sk = skill || {};
    const row = document.createElement("div");
    row.className = "admin-skill-edit-row admin-ai-skill-editor-row";
    const t = aiSkillTypeChoice(sk);
    row.innerHTML = `
        <input class="ai-sk-name" type="text" placeholder="ط·آ·ط¢آ§ط·آ·ط¢آ³ط·آ¸أ¢â‚¬آ¦ ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ¸أ¢â‚¬آ¦ط·آ¸أ¢â‚¬طŒط·آ·ط¢آ§ط·آ·ط¢آ±ط·آ·ط¢آ© (ط·آ·ط¢آ¥ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ²ط·آ·ط¢آ§ط·آ¸أ¢â‚¬آ¦ط·آ¸ط¸آ¹)" value="${escapeAttr(sk.name || "")}">
        <select class="ai-sk-type">${skillTypeOptionsHtml(t)}</select>
        <input class="ai-sk-damage" type="number" step="any" placeholder="ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ¶ط·آ·ط¢آ±ط·آ·ط¢آ± (ط·آ¸ط¸آ¹ط·آ¸ط¹ث†ط·آ¸أ¢â‚¬ع‘ط·آ·ط¢آ±ط·آ¸ط¹ع©ط·آ¸أ¢â‚¬ع©ط·آ·ط¢آ¨ ط·آ¸أ¢â‚¬â€چط·آ¸أ¢â‚¬آ¦ط·آ·ط¢آ¶ط·آ·ط¢آ§ط·آ·ط¢آ¹ط·آ¸ط¸آ¾ط·آ·ط¢آ§ط·آ·ط¹آ¾ 50 ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ¶ط·آ·ط¢آ±ط·آ·ط¢آ¨ط·آ·ط¢آ§ط·آ·ط¹آ¾ ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ¸أ¢â‚¬طŒط·آ·ط¢آ¬ط·آ¸ط«â€ ط·آ¸أ¢â‚¬آ¦)" value="${escapeAttr(sk.damage ?? "")}">
        <input class="ai-sk-cooldown" type="number" step="any" placeholder="ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ·ط¹آ¾ط·آ¸أ¢â‚¬طŒط·آ·ط¢آ¯ط·آ·ط¢آ¦ط·آ·ط¢آ© (ط·آ·ط¢آ£ط·آ·ط¢آ¯ط·آ¸ط«â€ ط·آ·ط¢آ§ط·آ·ط¢آ±)" value="${escapeAttr(sk.cooldown ?? "")}">
        <input class="ai-sk-desc" type="text" placeholder="ط·آ¸ط«â€ ط·آ·ط¢آµط·آ¸ط¸آ¾ ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ¸أ¢â‚¬آ¦ط·آ¸أ¢â‚¬طŒط·آ·ط¢آ§ط·آ·ط¢آ±ط·آ·ط¢آ© (ط·آ·ط¢آ§ط·آ·ط¢آ®ط·آ·ط¹آ¾ط·آ¸ط¸آ¹ط·آ·ط¢آ§ط·آ·ط¢آ±ط·آ¸ط¸آ¹)" value="${escapeAttr(sk.description || "")}">
        <button type="button" class="admin-btn" onclick="removeSkillEditorRow(this, '${editorId}')">ط¸â€¹ط¹ط›أ¢â‚¬â€‌أ¢â‚¬ع©ط£آ¯ط¢آ¸ط¹ث†</button>
    `;
    editor.appendChild(row);
}

function removeSkillEditorRow(btn, editorId){
    const row = btn.closest(".admin-ai-skill-editor-row");
    if(!row) return;
    const editor = document.getElementById(editorId);
    row.remove();
    if(editor && !editor.querySelector(".admin-ai-skill-editor-row")){
        editor.innerHTML = `<div class="admin-skills-empty">ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ§ ط·آ¸أ¢â‚¬آ¦ط·آ¸أ¢â‚¬طŒط·آ·ط¢آ§ط·آ·ط¢آ±ط·آ·ط¢آ§ط·آ·ط¹آ¾ ط·آ·ط¢آ¨ط·آ·ط¢آ¹ط·آ·ط¢آ¯ ط£آ¢أ¢â€ڑآ¬أ¢â‚¬â€Œ ط·آ·ط¢آ£ط·آ·ط¢آ¶ط·آ¸ط¸آ¾ط·آ¸أ¢â‚¬طŒط·آ·ط¢آ§ ط·آ¸ط¸آ¹ط·آ·ط¢آ¯ط·آ¸ط«â€ ط·آ¸ط¸آ¹ط·آ¸أ¢â‚¬آ¹ط·آ·ط¢آ§ ط·آ·ط¢آ£ط·آ¸ط«â€  ط·آ·ط¢آ§ط·آ¸أ¢â‚¬آ ط·آ·ط¢آ³ط·آ·ط¢آ® ط·آ·ط¢آ§ط·آ¸أ¢â‚¬ع‘ط·آ·ط¹آ¾ط·آ·ط¢آ±ط·آ·ط¢آ§ط·آ·ط¢آ­ ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ¸أ¢â‚¬آ¦ط·آ·ط¢آ³ط·آ·ط¢آ§ط·آ·ط¢آ¹ط·آ·ط¢آ¯ ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ°ط·آ¸ط¦â€™ط·آ¸ط¸آ¹ ط·آ¸أ¢â‚¬â€چط·آ¸أ¢â‚¬آ¦ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ¦ط·آ¸أ¢â‚¬طŒط·آ·ط¢آ§.</div>`;
    }
}

// ط·آ¸ط¸آ¹ط·آ·ط¢آ¬ط·آ¸أ¢â‚¬آ¦ط·آ·ط¢آ¹ ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ¸أ¢â‚¬آ¦ط·آ¸أ¢â‚¬طŒط·آ·ط¢آ§ط·آ·ط¢آ±ط·آ·ط¢آ§ط·آ·ط¹آ¾ ط·آ¸أ¢â‚¬آ¦ط·آ¸أ¢â‚¬آ  ط·آ¸أ¢â‚¬آ¦ط·آ·ط¢آ­ط·آ·ط¢آ±ط·آ·ط¢آ± ط·آ¸أ¢â‚¬آ¦ط·آ·ط¢آ¹ط·آ¸ط¸آ¹ط·آ¸أ¢â‚¬ع©ط·آ¸أ¢â‚¬آ  ط·آ·ط¢آ¨ط·آ·ط¢آµط·آ¸ط¸آ¹ط·آ·ط·â€؛ط·آ·ط¢آ© ط·آ¸أ¢â‚¬ع‘ط·آ·ط¢آ§ط·آ·ط¢آ¨ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ© ط·آ¸أ¢â‚¬â€چط·آ¸أ¢â‚¬â€چط·آ·ط¢آ¥ط·آ¸أ¢â‚¬آ ط·آ·ط¢آ´ط·آ·ط¢آ§ط·آ·ط·إ’ (ط·آ¸ط¸آ¹ط·آ·ط¢آ³ط·آ·ط¹آ¾ط·آ·ط¢آ¨ط·آ·ط¢آ¹ط·آ·ط¢آ¯ ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ·ط¢آµط·آ¸ط¸آ¾ط·آ¸ط«â€ ط·آ¸ط¸آ¾ ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ¸ط¸آ¾ط·آ·ط¢آ§ط·آ·ط¢آ±ط·آ·ط·â€؛ط·آ·ط¢آ©).
function collectSkillEditorRows(editorId){
    const editor = document.getElementById(editorId);
    if(!editor) return [];
    const rows = [];
    editor.querySelectorAll(".admin-ai-skill-editor-row").forEach(row => {
        const name = (row.querySelector(".ai-sk-name") || {}).value || "";
        if(!name.trim()) return;
        rows.push({
            name: name.trim(),
            type: (row.querySelector(".ai-sk-type") || {}).value || "attack",
            damage: Number((row.querySelector(".ai-sk-damage") || {}).value) || 0,
            cooldown: Number((row.querySelector(".ai-sk-cooldown") || {}).value) || 0,
            description: ((row.querySelector(".ai-sk-desc") || {}).value || "").trim()
        });
    });
    return rows;
}

